import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load ceramic grain texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  imageTexture.colorSpace = THREE.SRGBColorSpace;
  imageTexture.magFilter = THREE.LinearFilter;
  imageTexture.minFilter = THREE.LinearMipmapLinearFilter;

  // Create plane geometry matching 512:320 aspect ratio (1.6:1)
  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  // TSL material: textured plane
  const colorNode = textureNode(imageTexture);
  const material = new MeshBasicNodeMaterial({
    colorNode,
    side: THREE.DoubleSide,
    transparent: true,
  });

  // Mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene position
  const pos = config.scenePosition;
  group.position.set(pos.x, pos.y, pos.z);

  if (pos.rotationXYZ) {
    group.rotation.order = 'XYZ';
    group.rotation.set(
      pos.rotationXYZ[0] || 0,
      pos.rotationXYZ[1] || 0,
      pos.rotationXYZ[2] || 0
    );
  }

  if (pos.scaleXYZ) {
    group.scale.set(
      pos.scaleXYZ[0] || 1,
      pos.scaleXYZ[1] || 1,
      pos.scaleXYZ[2] || 1
    );
  }

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
  };

  // Handlers
  group.userData.handlers = {};

  return group;
}
